function openDialog(title,eyebrow,fields,record,saveFn){const dlg=$('#recordDialog');$('#dialogTitle').textContent=title;$('#dialogEyebrow').textContent=eyebrow;$('#dialogBody').innerHTML=fields;dlg.showModal();const form=$('#recordForm');const saveBtn=$('#dialogSave');const handler=e=>{if(e.submitter!==saveBtn)return;e.preventDefault();const result=saveFn(new FormData(form));if(result!==false){dlg.close();}};form.addEventListener('submit',handler);dlg.addEventListener('close',()=>form.removeEventListener('submit',handler),{once:true});}
