function editMcq(id){const q=data.questions.find(x=>x.id===id),isNew=!q;openDialog(isNew?'Add MCQ question':'Edit MCQ question','QUESTION BANK',field('Question','prompt',q?.prompt||'','textarea',{required:true,span:true,rows:3})+field('Subject','subject',q?.subject||'','select',{required:true,options:data.subjects.map(s=>({value:s.name,label:s.name}))})+field('Topic (optional)','topic',q?.topic||'','text')+field('Option A','o0',q?.options?.[0]||'','text',{required:true,span:true})+field('Option B','o1',q?.options?.[1]||'','text',{required:true,span:true})+field('Option C','o2',q?.options?.[2]||'','text',{required:true,span:true})+field('Option D','o3',q?.options?.[3]||'','text',{required:true,span:true})+field('Correct option','correct',q?.correct??0,'select',{options:['A','B','C','D'].map((x,i)=>({value:i,label:x}))})+field('Explanation','explanation',q?.explanation||'','textarea',{span:true}),q,fd=>{const prompt=fd.get('prompt').trim(),opts=[0,1,2,3].map(i=>fd.get('o'+i).trim());if(!prompt||opts.some(x=>!x))return toast('Add a question and all four answer options.'),false;const obj={prompt,subject:fd.get('subject'),topic:fd.get('topic').trim(),options:opts,correct:Number(fd.get('correct')),explanation:fd.get('explanation').trim(),sample:false};if(isNew)data.questions.push({id:uid('question'),...obj});else Object.assign(q,obj);save();initMcq();renderSelects();toast(isNew?'Question added.':'Question updated.');});}
