function editSession(id){const s=data.sessions.find(x=>x.id===id);if(!s)return;openDialog('Edit study record','SESSION HISTORY',field('Study date','date',s.date,'date',{required:true})+field('Duration (minutes)','duration',s.duration,'number',{min:1,max:1440,required:true})+field('Subject','subjectId',s.subjectId||'','select',{options:optionsSubjects(s.subjectId)})+field('Topic','topicId',s.topicId||'','select',{options:optionsTopics(s.subjectId,s.topicId)})+field('Category','category',s.category||'Other','select',{options:['MCQs','Subjective Writing','Online Class','Reading/Revision','Other'].map(x=>({value:x,label:x}))})+field('Notes','notes',s.notes||'','textarea',{span:true}),s,fd=>{const duration=Number(fd.get('duration'));if(!fd.get('date')||!Number.isFinite(duration)||duration<=0)return toast('Date and positive duration are required.'),false;Object.assign(s,{date:fd.get('date'),duration:Math.round(duration),subjectId:fd.get('subjectId'),topicId:fd.get('topicId'),category:fd.get('category'),notes:fd.get('notes').trim()});save();renderAll();toast('Study record updated.');});}
function renderAll(){renderSelects();renderDashboard();renderSyllabus();renderPlanner();renderRevisions();renderWriting();renderHistory();renderMcq();renderAnalyticsIfVisible();applySettingsToUI();}
function applySettingsToUI(){const pref=data.settings.theme||'light';let theme=pref;if(pref==='system')theme=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.dataset.theme=theme;$('#examDate1').value=data.settings.examDate1;$('#examDate2').value=data.settings.examDate2;$('#dailyTarget').value=data.settings.dailyTarget;$('#themeSelect').value=pref;}
function exportData(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString(),app:'BarReady'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`barready-backup-${todayISO()}.json`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Backup downloaded. Keep it somewhere safe.');}
function validImport(obj){if(!obj||typeof obj!=='object'||Array.isArray(obj))return false;for(const k of ['subjects','sessions','tasks','revisions','questions','mcqHistory','writingTasks'])if(!Array.isArray(obj[k]))return false;if(!obj.settings||typeof obj.settings!=='object')return false;return obj.sessions.every(s=>s&&typeof s.id==='string'&&typeof s.date==='string'&&Number.isFinite(Number(s.duration))&&Number(s.duration)>0);}
async function importData(file){if(!file)return;try{const obj=JSON.parse(await file.text());if(!validImport(obj)){toast('That file does not look like a valid BarReady backup. Nothing changed.');return;}const ok=await confirmAction('Replace current data?','Importing this backup replaces the BarReady data currently saved in this browser. Export your current data first if you may need it.');if(!ok)return;data=normalizeData(obj);save();renderAll();initMcq();toast('Backup imported successfully.');}catch(e){toast('Could not read that JSON file. Nothing changed.');}finally{$('#importFile').value='';}}
