$('#timerModes').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b){if(timer.running){toast('Pause the current timer before changing modes.');return;}resetTimer(b.dataset.mode);}});
$('#timerStart').addEventListener('click',startTimer);$('#timerReset').addEventListener('click',()=>{resetTimer(timer.mode);toast('Timer reset. No session was saved.');});$('#timerFinish').addEventListener('click',finishTimer);$('#applyCustom').addEventListener('click',()=>{const n=Number($('#customMinutes').value);if(!Number.isInteger(n)||n<1||n>600){toast('Choose a custom duration from 1 to 600 minutes.');return;}if(timer.running){toast('Pause the timer before changing duration.');return;}timer.duration=n*60;timer.remaining=timer.duration;timer.elapsed=0;updateTimerUI();toast(`Custom timer set to ${n} minutes.`);});
$('#timerSubject').addEventListener('change',()=>{$('#timerTopic').innerHTML=topicOptions($('#timerSubject').value,'',true);});$('#logSubject').addEventListener('change',()=>{$('#logTopic').innerHTML=topicOptions($('#logSubject').value,'',true);});
$('#toggleLogForm').addEventListener('click',()=>{const form=$('#manualLogForm');form.classList.toggle('hidden');$('#toggleLogForm').textContent=form.classList.contains('hidden')?'＋ Add past study':'− Close form';if(!form.classList.contains('hidden'))$('#logDate').value=todayISO();});$('#cancelLog').addEventListener('click',()=>{$('#manualLogForm').reset();$('#manualLogForm').classList.add('hidden');$('#toggleLogForm').textContent='＋ Add past study';});
