$('#addSubjectBtn').addEventListener('click',()=>editSubject());$('#syllabusSearch').addEventListener('input',renderSyllabus);$('#syllabusStatusFilter').addEventListener('change',renderSyllabus);$('#syllabusPriorityFilter').addEventListener('change',renderSyllabus);
$('#addTaskBtn').addEventListener('click',()=>editTask());$('#plannerFilter').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;$$('#plannerFilter button').forEach(x=>x.classList.toggle('active',x===b));renderPlanner();});$('#plannerDateFilter').addEventListener('change',renderPlanner);$('#addRevisionBtn').addEventListener('click',()=>editRevision());$('#revisionFilter').addEventListener('change',renderRevisions);
